mpleted=tx.execute(st->output.complete(actor,"chunk-complete",id,binding));assertEquals(PcArtifactService.digest(bytes),completed.get("sha256"));assertEquals("ACTIVE",store.require(PcTable.ARTIFACT,id,false).getState());clock.advance(61);assertThrows(PcException.class,()->tx.execute(st->output.complete(actor,"chunk-complete",id,binding)));assertThrows(PcException.class,()->tx.execute(st->output.chunk(actor,"chunk-upload",id,part)));
