    private PcRecord preSnapshot(String character,long sequence){return tx.execute(st->{PcRecord row=store.insert(PcTable.SNAPSHOT,workspace,1L,taskId,sessionId,runnerId,"SNAPSHOT","READY",null,Map.of("commitId",character.repeat(40),"phase","PRE_TURN"));row.setSequenceNumber(sequence);store.save(PcTable.SNAPSHOT,row,store.data(row));return row;});}
    private Map<String,Object> snapshotProof(String character){return Map.of("snapshotId",character.repeat(40),"currentFingerprint",ROOT,"files",List.of(Map.of("path","README.md","status","MODIFY","currentHash",ROOT,"targetHash","b".repeat(64),"currentMode",33188,"targetMode",33188)),"canRestore",true,"conflicts",List.of());}
    private Map<String,Object> completedPreview(PcRecord snapshot,String callId,boolean large){Map<String,Object> target=Map.of("snapshotMetadataId",snapshot.getId().toString(),"snapshotId","a".repeat(40),"snapshotVersion",snapshot.getVersion());Map<String,Object> request=proposal(callId,"snapshot__preview",target);Map<String,Object> permit=tx.execute(st->tools.propose(actor,callId+":propose",request));assertEquals("PERMITTED",permit.get("decision"));Map<String,Object> consume=new LinkedHashMap<>(request);consume.put("permitToken",permit.get("permitToken"));tx.execute(st->tools.permit(actor,callId+":consume",consume,true));Map<String,Object> proof=snapshotProof("a"),body=new LinkedHashMap<>(Map.of("restorePreview",proof,"currentFingerprint",ROOT,"commitId","a".repeat(40),"snapshotMetadataId",snapshot.getId().toString(),"snapshotVersion",snapshot.getVersion()));if(large){Map<String,Object> fullProof=new LinkedHashMap<>(proof);Map<String,Object> file=new LinkedHashMap<>((Map<String,Object>)((List<?>)proof.get("files")).get(0));file.put("diff","真实大差异"+"x".repeat(80000));fullProof.put("files",List.of(file));Map<String,Object> fullBody=new LinkedHashMap<>(body);fullBody.put("restorePreview",fullProof);Map<String,Object> artifact=tx.execute(st->artifacts.storeRunnerOutput(workspace,1,sessionId,taskId,callId,store.json.write(fullBody)));body.put("previewArtifactId",artifact.get("id"));body.put("previewArtifactSha256",artifact.get("sha256"));body.put("previewArtifactSize",artifact.get("size"));}Map<String,Object> result=receipt(request,permit);result.put("beforeHash",ROOT);result.put("afterHash",ROOT);result.put("result",Map.of("text",store.json.write(body)));tx.execute(st->tools.receipt(actor,callId+":receipt",result));Map<String,Object> finalArgs=new LinkedHashMap<>(target);finalArgs.put("offset",1);finalArgs.put("previewToolCallId",callId);finalArgs.put("currentFingerprint",ROOT);finalArgs.put("restorePreview",proof);return finalArgs;}
    private PcRecord mcpConfig(String name,String state){return tx.execute(st->store.insert(PcTable.MCP_CONFIG,workspace,1L,null,null,null,"MCP",state,null,Map.of("name",name,"transport","HTTP","configHash",ROOT,"trustedHash",ROOT,"configurationVersion",1)));}
    private Map<String,Object> outputRef(String call,String content){Map<String,Object> artifact=tx.execute(st->artifacts.storeRunnerOutput(workspace,1,sessionId,taskId,call,content));return Map.of("eventArtifactId",artifact.get("id"),"eventArtifactSha256",artifact.get("sha256"),"eventArtifactSize",artifact.get("size"));}
    private Map<String,Object> catalogueRef(String call,Map<String,Object> payload){Map<String,Object> projection=new LinkedHashMap<>();for(String field:List.of("kind","configId","configVersion","status"))projection.put(field,payload.get(field));Map<String,Object> digests=new LinkedHashMap<>();for(String field:List.of("tools","resources","prompts"))if(payload.containsKey(field))digests.put(field,Map.of("sha256",store.json.hash(payload.get(field)),"size",store.json.write(payload.get(field)).getBytes(java.nio.charset.StandardCharsets.UTF_8).length));projection.put("catalogueDigests",digests);projection.putAll(outputRef(call,store.json.write(Map.of("taskId",String.valueOf(taskId),"sessionId",String.valueOf(sessionId),"type","CONNECTION_RESULT","payload",payload))));return projection;}
    private void completeCurrentCall(String callId){PcRecord call=store.mapper.findKey(PcTable.TOOL_CALL,"task:"+taskId+":call:"+callId,false);Map<String,Object> p=store.data(call),response=Map.of("permitToken",crypto.open(call.getUniqueKey(),PcJson.text(p,"permitCipher")));tx.execute(st->tools.receipt(actor,callId+":completed",receipt(p,response)));}
    private void setControl(String operation,Map<String,Object> arguments){tx.executeWithoutResult(st->{PcRecord task=store.require(PcTable.TASK,taskId,true);Map<String,Object> data=store.data(task);data.put("operation",operation);data.put("arguments",arguments);task.setKind("CONTROL");store.save(PcTable.TASK,task,data);lease.put("version",task.getVersion());});}
    private void consumeRead(String id,String name,Map<String,Object> arguments){Map<String,Object> request=proposal(id,name,arguments);Map<String,Object> permitted=tx.execute(st->tools.propose(actor,id+":proposal",request));if("PENDING".equals(permitted.get("decision"))){PcRecord approval=store.require(PcTable.APPROVAL,PcJson.number(permitted,"approvalId"),false);tx.execute(st->tools.decision(1,approval.getId(),approval.getVersion(),id+":approve",Map.of("decision","APPROVE","inputHash",request.get("argsHash"))));permitted=tx.execute(st->tools.permit(actor,id+":permit",request,false));}Map<String,Object> consumed=new LinkedHashMap<>(request);consumed.put("permitToken",permitted.get("permitToken"));tx.execute(st->tools.permit(actor,id+":consume",consumed,true));}
    private void appendCompaction(long sequence,List<Map<String,Object>> messages){Map<String,Object> payload=new LinkedHashMap<>();payload.put("schemaVersion",1);payload.put("sequence",sequence);payload.put("timestamp",clock.instant().toEpochMilli());payload.put("event","compaction");payload.put("mode","react");payload.put("actor","agent");payload.put("source","automatic");payload.put("metadata",Map.of("beforeTokens",200,"afterTokens",20,"derivedMessages",messages));payload.put("message",null);sendEvent("source-compaction-"+sequence,"LEDGER_MESSAGE",payload);}
    private void sendEvent(String id,String type,Map<String,Object> payload){Map<String,Object> input=identity();input.put("eventId",id);input.put("type",type);input.put("payload",payload);tx.execute(st->runner.event(actor,id,input));}
